// n46 köy v2 model contract: for every catalogue model, how big it stands in
// the village (pinned scale), what it covers on the ground and overhead,
// where its doors are, what ground it needs (dry land, a river bank, a lake,
// a crossing, a railway) and how much space it wants in front. The numbers
// come from the drawings (modelData.js, regenerated by
// scripts/koy/measure-models.mjs and checked by the atlas test).
//
// A placement stores its model's geometry version and scale. A later
// drawing change gets a new version; an old placement keeps its old numbers.
import { MODEL_DATA } from "./modelData.js";
import { MONUMENTS } from "../olcek.js";

export const GEOMETRY_VERSION = 2;
// What changed in each geometry version. A placement keeps the version it was
// made with; a newer version never quietly redraws an older placement.
//   1  the drawings as measured in package B
//   2  Anıtkabir 1.25× (Batur's choice on 21 Oct 2026, card "B · 1,25×"): the
//      Hall of Honour about 28 m against a 2-storey house, about 1.4 times its
//      height (the real ratio is about 2; 1.5× filled a phone screen alone)
const VERSION_SCALE = { 2: { anitkabir: 1.25 } };
const scaleAt = (id, version) => {
  let k = 1;
  for (let v = 2; v <= version; v++) k *= VERSION_SCALE[v]?.[id] || 1;
  return k;
};
// What ground a model needs (plan §4.3 terrainContext).
export const CONTEXT = {
  sudegirmeni: "bank", // the wheel turns in a flowing river
  yuzenev: "lake", // floats, with a jetty to the shore
  fener: "shore", // stands on the lake shore
  asmakopru: "bridge", // spans the river between two landings
  kemer: "bridge",
  istasyon: "rail", // platform along the railway
};
// How the water and rail models sit on their context, read off their drawings
// (src/rareBuildings.js, src/rareBuildings2.js, src/vernacular.js) in drawing
// units; modelSpec() multiplies by the model's scale. Local facing-0 axes.
//   door:  the public entrance when it is not centred on the +y wall
//   wet:   points that must stand in the river (the mill wheel)
//   dry:   the part that must stay on dry ground (the mill body, the platform)
//   track: the rails drawn with the model, laid on the railway (local y, x0..x1)
//   span:  the deck crosses the river along local x (the river runs along y)
const FIT = {
  kugulupark: { door: { x: 0, y: 7.5, dir: [0, 1] } },
  sudegirmeni: { door: { x: 1.45, y: 0.37, dir: [1, 0] }, wet: [[-0.45, 1.48]], dry: [-1.45, -1.2, 1.45, 1.0] },
  istasyon: { door: { x: 0, y: -1.25, dir: [0, -1] }, track: { y: 1.98, x0: -2.5, x1: 2.5 }, dry: [-2.25, -1.25, 2.25, 1.4] },
  yuzenev: { door: { x: 3.0, y: 0.62, dir: [1, 0] } },
  // The Road of Lions runs along +y from the square to the İstiklal and
  // Hürriyet towers; the visitors come in at its head, east of the centre.
  anitkabir: { door: { x: 0.96, y: 1.69, dir: [0, 1] } },
  asmakopru: { span: true },
  kemer: { span: true },
};
const times = (v, k) => (Array.isArray(v) ? v.map((x) => times(x, k)) : typeof v === "number" ? v * k : v);

// Landmarks get a plot of their own with a forecourt and an approach road.
const LANDMARK_SIZE = 5;
// (A bridge is long, not a landmark: its plot is the crossing itself.)
export const isLandmark = (id) => MONUMENTS.has(id) || (!CONTEXT[id] && Math.max(...MODEL_DATA[id].over.map(Math.abs)) >= LANDMARK_SIZE);

// Space in front of the door (garden, steps, forecourt) and around the sides.
const FRONT = { cottage: 0.9, house: 1.1, tower: 1.1 };
const SIDE = 0.35;

const cache = new Map();
/** The model's contract at a geometry version (1 or 2). */
export function modelSpec(id, version = GEOMETRY_VERSION) {
  const key = `${id}@${version}`;
  if (cache.has(key)) return cache.get(key);
  const base = MODEL_DATA[id];
  if (!base || !(version >= 1 && version <= GEOMETRY_VERSION)) return null;
  const f = scaleAt(id, version);
  const m = f === 1 ? base : { ...base, k: base.k * f, hw: base.hw * f, ground: times(base.ground, f), over: times(base.over, f), h: base.h * f };
  const context = CONTEXT[id] || "dry";
  const landmark = isLandmark(id);
  const g = m.ground,
    o = m.over;
  const span = Math.max(g[2] - g[0], g[3] - g[1]);
  // Bridges are entered from both ends of the deck (along local x); every
  // other model has one public door, centred on its +y wall (src/iso.js).
  const fit = FIT[id] || {};
  const k = m.k;
  const entrances =
    context === "bridge"
      ? [
          { x: g[0], y: 0, dir: [-1, 0], type: "main" },
          { x: g[2], y: 0, dir: [1, 0], type: "main" },
        ]
      : fit.door
        ? [{ x: fit.door.x * k, y: fit.door.y * k, dir: fit.door.dir, type: "main" }]
        : [{ x: 0, y: g[3], dir: [0, 1], type: "main" }];
  const spec = {
    id,
    version,
    kind: m.kind,
    scale: m.k,
    ground: g,
    over: o,
    height: m.h,
    entrances,
    context,
    landmark,
    // Landmarks keep a forecourt a third of their size deep for the view and the crowd;
    // a bridge's landings are its front.
    front: landmark ? Math.max(3, span * 0.33) : context === "bridge" ? 0 : FRONT[m.kind] || 1,
    side: landmark ? 1.2 : SIDE,
    facings: [0, 1],
    fit: {
      wet: fit.wet ? times(fit.wet, k) : null,
      dry: fit.dry ? times(fit.dry, k) : null,
      track: fit.track ? { y: fit.track.y * k, x0: fit.track.x0 * k, x1: fit.track.x1 * k } : null,
    },
  };
  cache.set(key, spec);
  return spec;
}
export const MODEL_IDS = Object.keys(MODEL_DATA);

// ---------- transforms ----------
// Facing 1 is the mirrored drawing: local (x, y) becomes (y, x).
const flip = (r) => [r[1], r[0], r[3], r[2]];
export const localRect = (r, facing) => (facing ? flip(r) : r);
export const worldRect = (r, x, y, facing) => {
  const l = localRect(r, facing);
  return [x + l[0], y + l[1], x + l[2], y + l[3]];
};
export const turn = ([a, b], facing) => (facing ? [b, a] : [a, b]);
/** Doors of a placed model in world coordinates: point just outside the wall and outward direction. */
export function doorsAt(spec, x, y, facing) {
  return spec.entrances.map((e) => {
    const [ex, ey] = turn([e.x, e.y], facing),
      dir = turn(e.dir, facing);
    return { point: [x + ex + dir[0] * 0.25, y + ey + dir[1] * 0.25], dir, type: e.type };
  });
}
/** Ground rect, overhead rect and the plot (both, with garden margins) of a placement. */
export function shapeAt(spec, x, y, facing) {
  const ground = worldRect(spec.ground, x, y, facing),
    over = worldRect(spec.over, x, y, facing);
  const both = [Math.min(ground[0], over[0]), Math.min(ground[1], over[1]), Math.max(ground[2], over[2]), Math.max(ground[3], over[3])];
  const [dx, dy] = turn(spec.entrances[0].dir, facing);
  const s = spec.side,
    f = spec.front;
  // The front margin lies on the door side; the others get the side margin.
  const plot = [both[0] - s - (dx < 0 ? f : 0), both[1] - s - (dy < 0 ? f : 0), both[2] + s + (dx > 0 ? f : 0), both[3] + s + (dy > 0 ? f : 0)];
  return { ground, over, plot };
}
